import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";
import { startContractExpirationScheduler } from "./scheduler";

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // Start the contract expiration scheduler
  startContractExpirationScheduler();

  // ALWAYS serve the app on port 5000
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = 5000;
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertPropertySchema, insertOfferSchema, insertContractSchema, insertNotificationSchema, contracts } from "@shared/schema";
import { db } from "./db";
import { eq } from "drizzle-orm";
import { z } from "zod";

export async function registerRoutes(app: Express): Promise<Server> {
  // Properties routes
  app.get("/api/properties", async (req, res) => {
    try {
      const ownerId = req.query.ownerId ? parseInt(req.query.ownerId as string) : undefined;
      const properties = await storage.getProperties(ownerId);
      res.json(properties);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch properties" });
    }
  });

  app.get("/api/properties/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const property = await storage.getProperty(id);
      if (!property) {
        return res.status(404).json({ error: "Property not found" });
      }
      res.json(property);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch property" });
    }
  });

  app.post("/api/properties", async (req, res) => {
    try {
      const validatedData = insertPropertySchema.parse(req.body);
      const property = await storage.createProperty(validatedData);
      res.status(201).json(property);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid property data", details: error.errors });
      }
      res.status(500).json({ error: "Failed to create property" });
    }
  });

  app.put("/api/properties/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const updates = req.body;
      const property = await storage.updateProperty(id, updates);
      if (!property) {
        return res.status(404).json({ error: "Property not found" });
      }
      res.json(property);
    } catch (error) {
      res.status(500).json({ error: "Failed to update property" });
    }
  });

  // Offers routes
  app.get("/api/offers", async (req, res) => {
    try {
      const userId = parseInt(req.query.userId as string);
      const type = (req.query.type as 'sent' | 'received') || 'sent';
      const offers = await storage.getOffers(userId, type);
      res.json(offers);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch offers" });
    }
  });

  app.post("/api/offers", async (req, res) => {
    try {
      const validatedData = insertOfferSchema.parse(req.body);
      const offer = await storage.createOffer(validatedData);

      // Create notification for property owner
      await storage.createNotification({
        userId: offer.ownerId,
        title: "Nouvelle offre reçue",
        message: `Vous avez reçu une nouvelle offre pour votre propriété`,
        type: "offer",
        relatedId: offer.id,
      });

      res.status(201).json(offer);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid offer data", details: error.errors });
      }
      res.status(500).json({ error: "Failed to create offer" });
    }
  });

  app.put("/api/offers/:id/status", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const { status } = req.body;
      const offer = await storage.updateOfferStatus(id, status);

      if (!offer) {
        return res.status(404).json({ error: "Offer not found" });
      }

      // Create notification for tenant
      const notificationMessage = status === 'accepted' ? 
        "Votre offre a été acceptée! Vous pouvez maintenant demander un contrat." : 
        "Votre offre a été refusée";

      await storage.createNotification({
        userId: offer.tenantId,
        title: status === 'accepted' ? "Offre acceptée" : "Offre refusée",
        message: notificationMessage,
        type: "offer",
        relatedId: offer.id,
      });

      res.json(offer);
    } catch (error) {
      res.status(500).json({ error: "Failed to update offer status" });
    }
  });

  // Contract request endpoint (tenant requests contract after accepted offer)
  app.put("/api/offers/:id/request-contract", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const offer = await storage.updateOfferStatus(id, "contract_requested");

      if (!offer) {
        return res.status(404).json({ error: "Offer not found" });
      }

      // Create notification for owner
      await storage.createNotification({
        userId: offer.ownerId,
        title: "Demande de contrat",
        message: "Un locataire demande la création d'un contrat pour son offre acceptée",
        type: "contract_request",
        relatedId: offer.id,
      });

      res.json(offer);
    } catch (error) {
      res.status(500).json({ error: "Failed to request contract" });
    }
  });

  // Contracts routes
  app.get("/api/contracts", async (req, res) => {
    try {
      const userId = parseInt(req.query.userId as string);
      const ownerOnly = req.query.ownerOnly === 'true';

      const contracts = ownerOnly ? 
        await storage.getOwnerContracts(userId) : 
        await storage.getContracts(userId);
      res.json(contracts);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contracts" });
    }
  });

  app.get("/api/contracts/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const contract = await storage.getContract(id);
      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }
      res.json(contract);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contract" });
    }
  });

  app.post("/api/contracts", async (req, res) => {
    try {
      console.log("Received contract data:", req.body);
      const validatedData = insertContractSchema.parse(req.body);

      // Verify that the offer exists and is in contract_requested status
      const offer = await storage.getOffer(validatedData.offerId);
      if (!offer) {
        return res.status(400).json({ error: "Offer not found" });
      }
      if (offer.status !== "contract_requested") {
        return res.status(400).json({ error: "Contract can only be created for requested offers" });
      }

      const contract = await storage.createContract(validatedData);

      // Create notification for tenant
      await storage.createNotification({
        userId: contract.tenantId,
        title: "Contrat créé",
        message: "Un contrat a été créé pour votre offre. Attendez la signature du propriétaire.",
        type: "contract",
        relatedId: contract.id,
      });

      res.status(201).json(contract);
    } catch (error) {
      console.error("Contract creation error:", error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid contract data", details: error.errors });
      }
      res.status(500).json({ error: "Failed to create contract", details: (error as Error).message });
    }
  });

  app.put("/api/contracts/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const updates = req.body;

      // Check if contract exists and can be modified
      const existingContract = await storage.getContract(id);
      if (!existingContract) {
        return res.status(404).json({ error: "Contract not found" });
      }

      // Only allow modifications if tenant hasn't signed yet
      if (existingContract.tenantSignature) {
        return res.status(400).json({ error: "Cannot modify contract after tenant signature" });
      }

      // Reset owner signature if contract data is modified
      const resetSignature = {
        ownerSignature: null,
        ownerSignedAt: null,
        tenantSignDeadline: null,
        status: 'draft'
      };

      const contract = await storage.updateContract(id, { ...updates, ...resetSignature });
      res.json(contract);
    } catch (error) {
      res.status(500).json({ error: "Failed to update contract" });
    }
  });

  app.put("/api/contracts/:id/sign", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const { signatureType, signatureData } = req.body;

      if (!['owner', 'tenant'].includes(signatureType)) {
        return res.status(400).json({ error: "Invalid signature type" });
      }

      const contract = await storage.updateContractSignature(id, signatureType, signatureData);

      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }

      // Handle owner signature - set 3-day deadline for tenant
      if (signatureType === 'owner' && contract.status === 'owner_signed') {
        // Set tenant sign deadline to 3 days from now
        const deadline = new Date();
        deadline.setDate(deadline.getDate() + 3);
        await storage.updateContractDeadline(id, deadline);

        // Notify tenant with deadline
        await storage.createNotification({
          userId: contract.tenantId,
          title: "Nouveau contrat à signer",
          message: `Le propriétaire a signé le contrat. Vous avez 3 jours pour le signer avant expiration (deadline: ${deadline.toLocaleDateString('fr-FR')})`,
          type: "contract_signature_required",
          relatedId: contract.id,
        });
      }

      // Handle tenant signature - activate contract and update property
      if (signatureType === 'tenant' && contract.status === 'fully_signed') {
        // Check if tenant signed within deadline
        const currentContract = await storage.getContract(id);
        if (currentContract?.tenantSignDeadline && new Date() > new Date(currentContract.tenantSignDeadline)) {
          return res.status(400).json({ error: "Contract expired. Signing deadline has passed." });
        }

        // Check for other active contracts on this property
        const existingActiveContract = await storage.getActiveContractForProperty(contract.propertyId);
        if (existingActiveContract) {
          return res.status(400).json({ error: "This property already has an active contract." });
        }

        // Activate contract and update property status
        await storage.updateContractStatus(id, 'active');
        await storage.updatePropertyStatus(contract.propertyId, 'Loué');

        // Notify owner that contract is fully signed and active
        await storage.createNotification({
          userId: contract.ownerId,
          title: "Contrat activé",
          message: "Le locataire a signé le contrat. Le contrat est maintenant actif et la propriété est marquée comme louée.",
          type: "contract_active",
          relatedId: contract.id,
        });
      }

      res.json(contract);
    } catch (error) {
      console.error("Contract signing error:", error);
      res.status(500).json({ error: "Failed to sign contract" });
    }
  });

  // Notifications routes
  app.get("/api/notifications", async (req, res) => {
    try {
      const userId = parseInt(req.query.userId as string);
      const notifications = await storage.getNotifications(userId);
      res.json(notifications);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch notifications" });
    }
  });

  app.put("/api/notifications/:id/read", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const success = await storage.markNotificationRead(id);
      if (!success) {
        return res.status(404).json({ error: "Notification not found" });
      }
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ error: "Failed to mark notification as read" });
    }
  });

  app.put("/api/notifications/:id/read", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const success = await storage.markNotificationRead(id);
      if (!success) {
        return res.status(404).json({ error: "Notification not found" });
      }
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ error: "Failed to mark notification as read" });
    }
  });

  // Contract expiration check endpoint
  app.post("/api/contracts/expire-check", async (req, res) => {
    try {
      await storage.expireContracts();
      res.json({ success: true, message: "Contract expiration check completed" });
    } catch (error) {
      res.status(500).json({ error: "Failed to check contract expiration" });
    }
  });

  // Contract modification
  app.put("/api/contracts/:id/modify", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const { contractData } = req.body;

      const contract = await storage.getContract(id);
      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }

      // Only allow modification if contract is not fully signed yet
      if (contract.status === 'active') {
        return res.status(400).json({ error: "Cannot modify an active contract" });
      }

      // Reset signatures if contract data is modified
      const [updated] = await db
        .update(contracts)
        .set({ 
          contractData, 
          ownerSignature: null, 
          tenantSignature: null,
          ownerSignedAt: null,
          tenantSignedAt: null,
          status: 'draft',
          tenantSignDeadline: null,
          updatedAt: new Date() 
        })
        .where(eq(contracts.id, id))
        .returning();

      // Notify both parties about the modification
      await storage.createNotification({
        userId: contract.ownerId,
        title: "Contrat modifié",
        message: "Le contrat a été modifié. Veuillez le réviser et le signer à nouveau.",
        type: "contract_modified",
        relatedId: contract.id,
      });

      await storage.createNotification({
        userId: contract.tenantId,
        title: "Contrat modifié",
        message: "Le contrat a été modifié par le propriétaire. Les signatures précédentes ont été supprimées.",
        type: "contract_modified",
        relatedId: contract.id,
      });

      res.json(updated);
    } catch (error) {
      console.error("Contract modification error:", error);
      res.status(500).json({ error: "Failed to modify contract" });
    }
  });

  // Contract PDF download
  app.get("/api/contracts/:id/download", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const contract = await storage.getContract(id);

      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }

      // Only allow download if contract is fully signed
      if (contract.status !== 'active' && contract.status !== 'fully_signed') {
        return res.status(400).json({ error: "Contract must be fully signed to download" });
      }

      // Generate PDF URL (in real implementation, this would generate/retrieve actual PDF)
      const pdfUrl = `/api/contracts/${id}/pdf`;

      res.json({ 
        downloadUrl: pdfUrl,
        filename: `contrat_${id}_${contract.contractData?.propertyTitle?.replace(/\s+/g, '_')}.pdf`
      });
    } catch (error) {
      res.status(500).json({ error: "Failed to generate download link" });
    }
  });

  // Mock authentication route (replace with real auth later)
  app.post("/api/auth/login", async (req, res) => {
    const { username, password } = req.body;

    // Mock user for testing
    const mockUser = {
      id: 1,
      username: "test_user",
      userType: "tenant",
      email: "test@example.com",
      firstName: "Test",
      lastName: "User",
    };

    res.json({ user: mockUser, token: "mock-token" });
  });

  const httpServer = createServer(app);
  return httpServer;
}

server/storage.ts.content:
import { 
  users, properties, offers, contracts, notifications,
  type User, type InsertUser, type Property, type InsertProperty,
  type Offer, type InsertOffer, type Contract, type InsertContract,
  type Notification, type InsertNotification 
} from "@shared/schema";
import { db } from "./db";
import { eq, desc, and, lt, or } from "drizzle-orm";

export interface IStorage {
  // User operations
  getUser(id: number): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  // Property operations
  getProperties(ownerId?: number): Promise<Property[]>;
  getProperty(id: number): Promise<Property | undefined>;
  createProperty(property: InsertProperty): Promise<Property>;
  updateProperty(id: number, updates: Partial<InsertProperty>): Promise<Property | undefined>;
  deleteProperty(id: number): Promise<boolean>;

  // Offer operations
  getOffers(userId: number, type: 'sent' | 'received'): Promise<Offer[]>;
  getOffer(id: number): Promise<Offer | undefined>;
  createOffer(offer: InsertOffer): Promise<Offer>;
  updateOfferStatus(id: number, status: string): Promise<Offer | undefined>;

  // Contract operations
  getContracts(userId: number): Promise<Contract[]>;
  getOwnerContracts(ownerId: number): Promise<Contract[]>;
  getContract(id: number): Promise<Contract | undefined>;
  createContract(contract: InsertContract): Promise<Contract>;
  updateContract(id: number, updates: Partial<InsertContract>): Promise<Contract | undefined>;
  updateContractSignature(id: number, signatureType: 'owner' | 'tenant', signatureData: string): Promise<Contract | undefined>;
  updateContractDeadline(id: number, deadline: Date): Promise<void>;
  updateContractStatus(id: number, status: string): Promise<void>;
  getActiveContractForProperty(propertyId: number): Promise<Contract | undefined>;
  updatePropertyStatus(propertyId: number, status: string): Promise<void>;
  expireContracts(): Promise<void>;

  // Notification operations
  getNotifications(userId: number): Promise<Notification[]>;
  createNotification(notification: InsertNotification): Promise<Notification>;
  markNotificationRead(id: number): Promise<boolean>;
}

export class DatabaseStorage implements IStorage {
  // User operations
  async getUser(id: number): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.id, id));
    return user || undefined;
  }

  async getUserByUsername(username: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.username, username));
    return user || undefined;
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const [user] = await db
      .insert(users)
      .values(insertUser)
      .returning();
    return user;
  }

  // Property operations
  async getProperties(ownerId?: number): Promise<Property[]> {
    if (ownerId) {
      return await db.select().from(properties).where(eq(properties.ownerId, ownerId));
    }
    return await db.select().from(properties).orderBy(desc(properties.createdAt));
  }

  async getProperty(id: number): Promise<Property | undefined> {
    const [property] = await db.select().from(properties).where(eq(properties.id, id));
    return property || undefined;
  }

  async createProperty(property: InsertProperty): Promise<Property> {
    const [newProperty] = await db
      .insert(properties)
      .values(property)
      .returning();
    return newProperty;
  }

  async updateProperty(id: number, updates: Partial<InsertProperty>): Promise<Property | undefined> {
    const [updated] = await db
      .update(properties)
      .set({ ...updates, updatedAt: new Date() })
      .where(eq(properties.id, id))
      .returning();
    return updated || undefined;
  }

  async deleteProperty(id: number): Promise<boolean> {
    const result = await db.delete(properties).where(eq(properties.id, id));
    return result.rowCount ? result.rowCount > 0 : false;
  }

  // Offer operations
  async getOffers(userId: number, type: 'sent' | 'received'): Promise<Offer[]> {
    const field = type === 'sent' ? offers.tenantId : offers.ownerId;
    return await db.select().from(offers)
      .where(eq(field, userId))
      .orderBy(desc(offers.createdAt));
  }

  async getOffer(id: number): Promise<Offer | undefined> {
    const [offer] = await db.select().from(offers).where(eq(offers.id, id));
    return offer || undefined;
  }

  async createOffer(offer: InsertOffer): Promise<Offer> {
    const [newOffer] = await db
      .insert(offers)
      .values(offer)
      .returning();
    return newOffer;
  }

  async updateOfferStatus(id: number, status: string): Promise<Offer | undefined> {
    const [updated] = await db
      .update(offers)
      .set({ status, updatedAt: new Date() })
      .where(eq(offers.id, id))
      .returning();
    return updated || undefined;
  }

  // Contract operations
  async getContracts(userId: number): Promise<Contract[]> {
    return await db.select().from(contracts)
      .where(or(eq(contracts.ownerId, userId), eq(contracts.tenantId, userId)))
      .orderBy(desc(contracts.createdAt));
  }

  async getOwnerContracts(ownerId: number): Promise<Contract[]> {
    return await db.select().from(contracts)
      .where(eq(contracts.ownerId, ownerId))
      .orderBy(desc(contracts.createdAt));
  }

  async getContract(id: number): Promise<Contract | undefined> {
    const [contract] = await db.select().from(contracts).where(eq(contracts.id, id));
    return contract || undefined;
  }

  async createContract(contract: InsertContract): Promise<Contract> {
    const [newContract] = await db
      .insert(contracts)
      .values(contract)
      .returning();
    return newContract;
  }

  async updateContract(id: number, updates: Partial<InsertContract>): Promise<Contract | undefined> {
    const [updated] = await db
      .update(contracts)
      .set({ ...updates, updatedAt: new Date() })
      .where(eq(contracts.id, id))
      .returning();
    return updated || undefined;
  }

  async updateContractSignature(id: number, signatureType: 'owner' | 'tenant', signatureData: string): Promise<Contract | undefined> {
    const updateData = signatureType === 'owner' ? 
      { ownerSignature: signatureData, ownerSignedAt: new Date(), status: 'owner_signed' } :
      { tenantSignature: signatureData, tenantSignedAt: new Date(), status: 'fully_signed' };

    const [updated] = await db
      .update(contracts)
      .set({ ...updateData, updatedAt: new Date() })
      .where(eq(contracts.id, id))
      .returning();
    return updated || undefined;
  }

  // Notification operations
  async getNotifications(userId: number): Promise<Notification[]> {
    return await db.select().from(notifications)
      .where(eq(notifications.userId, userId))
      .orderBy(desc(notifications.createdAt));
  }

  async createNotification(notification: InsertNotification): Promise<Notification> {
    const [newNotification] = await db
      .insert(notifications)
      .values(notification)
      .returning();
    return newNotification;
  }

  async markNotificationRead(id: number): Promise<boolean> {
    const result = await db
      .update(notifications)
      .set({ read: true })
      .where(eq(notifications.id, id));
    return result.rowCount ? result.rowCount > 0 : false;
  }

  // Additional contract methods
  async updateContractDeadline(id: number, deadline: Date): Promise<void> {
    await db
      .update(contracts)
      .set({ tenantSignDeadline: deadline, updatedAt: new Date() })
      .where(eq(contracts.id, id));
  }

  async updateContractStatus(id: number, status: string): Promise<void> {
    await db
      .update(contracts)
      .set({ status, updatedAt: new Date() })
      .where(eq(contracts.id, id));
  }

  async getActiveContractForProperty(propertyId: number): Promise<Contract | undefined> {
    const [contract] = await db.select().from(contracts)
      .where(and(
        eq(contracts.propertyId, propertyId),
        eq(contracts.status, 'active')
      ));
    return contract || undefined;
  }

  async updatePropertyStatus(propertyId: number, status: string): Promise<void> {
    await db
      .update(properties)
      .set({ status, updatedAt: new Date() })
      .where(eq(properties.id, propertyId));
  }

  async expireContracts(): Promise<void> {
    // Find contracts that are past deadline and still waiting for tenant signature
    const expiredContracts = await db.select().from(contracts)
      .where(and(
        eq(contracts.status, 'owner_signed'),
        lt(contracts.tenantSignDeadline, new Date())
      ));

    for (const contract of expiredContracts) {
      // Update contract status to expired
      await this.updateContractStatus(contract.id, 'expired');

      // Reset property status back to available
      await this.updatePropertyStatus(contract.propertyId, 'Disponible');

      // Notify both parties
      await this.createNotification({
        userId: contract.ownerId,
        title: "Contrat expiré",
        message: "Le contrat a expiré car le locataire n'a pas signé dans les délais.",
        type: "contract_expired",
        relatedId: contract.id,
      });

      await this.createNotification({
        userId: contract.tenantId,
        title: "Contrat expiré",
        message: "Vous avez dépassé le délai de signature. Le contrat a expiré.",
        type: "contract_expired",
        relatedId: contract.id,
      });
    }
  }
}

export const storage = new DatabaseStorage();

