import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useRoute, useLocation } from "wouter";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { insertOfferSchema } from "@shared/schema";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { z } from "zod";
import { MapPin, Home, Bed, Bath, Phone, MessageCircle, Banknote, ArrowLeft, Star, Heart, Share, Calendar, Users, Wifi, Car, Utensils, Tv, Wind, Droplets } from "lucide-react";
import Header from "@/components/Header";

type OfferFormData = z.infer<typeof insertOfferSchema>;

export default function PropertyDetails() {
  const [, params] = useRoute("/property/:id");
  const [, navigate] = useLocation();
  const [isOfferDialogOpen, setIsOfferDialogOpen] = useState(false);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const propertyId = params?.id ? parseInt(params.id) : 0;

  // Get current user from localStorage
  const currentUser = JSON.parse(localStorage.getItem("user") || '{"id": 4, "userType": "tenant"}');

  const { data: property, isLoading, error } = useQuery({
    queryKey: ["/api/properties", propertyId],
    queryFn: () => fetch(`/api/properties/${propertyId}`).then(res => {
      if (!res.ok) {
        throw new Error('Property not found');
      }
      return res.json();
    }),
    enabled: propertyId > 0,
  });

  const form = useForm<OfferFormData>({
    resolver: zodResolver(insertOfferSchema),
    defaultValues: {
      propertyId: propertyId,
      tenantId: currentUser.id,
      ownerId: property?.ownerId || 0,
      startDate: new Date(),
      endDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000), // 1 year from now
      monthlyRent: property?.price || "0",
      deposit: property?.deposit || "0",
      conditions: "",
      status: "pending",
    },
  });

  const createOfferMutation = useMutation({
    mutationFn: (data: OfferFormData) => apiRequest("/api/offers", {
      method: "POST",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      toast({
        title: "Offre envoyée",
        description: "Votre offre a été envoyée au propriétaire avec succès!",
      });
      setIsOfferDialogOpen(false);
      form.reset();
      queryClient.invalidateQueries({ queryKey: ["/api/offers"] });
    },
    onError: () => {
      toast({
        title: "Erreur",
        description: "Impossible d'envoyer l'offre. Veuillez réessayer.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: OfferFormData) => {
    const offerData = {
      ...data,
      propertyId: propertyId,
      tenantId: currentUser.id,
      ownerId: property?.ownerId || 0,
    };
    createOfferMutation.mutate(offerData);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8">
          <div className="animate-pulse space-y-4">
            <div className="h-64 bg-gray-200 rounded-lg"></div>
            <div className="h-8 bg-gray-200 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200 rounded w-1/2"></div>
          </div>
        </div>
      </div>
    );
  }

  if (error || !property) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8 text-center">
          <h1 className="text-2xl font-bold mb-4">Propriété non trouvée</h1>
          <p className="text-muted-foreground mb-4">
            La propriété avec l'ID {propertyId} n'existe pas ou n'est plus disponible.
          </p>
          <Button onClick={() => navigate("/search")}>Retour à la recherche</Button>
        </div>
      </div>
    );
  }

  const canMakeOffer = currentUser.id && currentUser.id !== property.ownerId && property.status === "Disponible";

  const getAmenityIcon = (amenity: string) => {
    const amenityLower = amenity.toLowerCase();
    if (amenityLower.includes('wifi')) return <Wifi className="h-4 w-4" />;
    if (amenityLower.includes('parking')) return <Car className="h-4 w-4" />;
    if (amenityLower.includes('cuisine')) return <Utensils className="h-4 w-4" />;
    if (amenityLower.includes('tv')) return <Tv className="h-4 w-4" />;
    if (amenityLower.includes('climatisation')) return <Wind className="h-4 w-4" />;
    if (amenityLower.includes('chauffage')) return <Wind className="h-4 w-4" />;
    if (amenityLower.includes('piscine')) return <Droplets className="h-4 w-4" />;
    return <Star className="h-4 w-4" />;
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-6">
          <Button 
            variant="ghost" 
            onClick={() => navigate("/search")}
            className="flex items-center space-x-2"
          >
            <ArrowLeft className="h-4 w-4" />
            <span>Retour</span>
          </Button>

          <div className="flex items-center space-x-2">
            <Button variant="ghost" size="icon">
              <Heart className="h-4 w-4" />
            </Button>
            <Button variant="ghost" size="icon">
              <Share className="h-4 w-4" />
            </Button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Property Info */}
          <div className="lg:col-span-2 space-y-6">
            {/* Property Images */}
            {property.images && property.images.length > 0 ? (
              <div className="aspect-video bg-gray-100 rounded-lg overflow-hidden">
                <img
                  src={property.images[0]}
                  alt={property.title}
                  className="w-full h-full object-cover"
                />
              </div>
            ) : (
              <div className="aspect-video bg-gradient-to-br from-primary/20 to-secondary/20 rounded-lg flex items-center justify-center">
                <div className="text-center">
                  <Home className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
                  <p className="text-muted-foreground">Pas d'image disponible</p>
                </div>
              </div>
            )}

            {/* Property Details */}
            <Card className="glass">
              <CardHeader>
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <CardTitle className="text-2xl mb-2 gradient-text">{property.title}</CardTitle>
                    <div className="flex items-center text-muted-foreground mb-4">
                      <MapPin className="h-4 w-4 mr-2" />
                      <span>{property.address}</span>
                    </div>
                    <div className="flex items-center space-x-4 mb-4">
                      <div className="flex items-center space-x-1">
                        <Home className="h-4 w-4 text-primary" />
                        <span className="font-medium">{property.rooms || 'N/A'}</span>
                        <span className="text-sm text-muted-foreground">ch</span>
                      </div>
                      <div className="flex items-center space-x-1">
                        <Bath className="h-4 w-4 text-primary" />
                        <span className="font-medium">{property.bathrooms || 'N/A'}</span>
                        <span className="text-sm text-muted-foreground">sdb</span>
                      </div>
                      {property.surface && (
                        <div className="flex items-center space-x-1">
                          <Users className="h-4 w-4 text-primary" />
                          <span className="font-medium">{property.surface}</span>
                          <span className="text-sm text-muted-foreground">m²</span>
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <Badge variant={property.status === "Disponible" ? "default" : "secondary"} className="mb-2">
                      {property.status}
                    </Badge>
                    <div className="text-3xl font-bold gradient-text">
                      {property.price} TND
                    </div>
                    <div className="text-sm text-muted-foreground">
                      /{property.priceType || 'mois'}
                    </div>
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                <div className="mb-6">
                  <p className="text-muted-foreground leading-relaxed">
                    {property.description}
                  </p>
                </div>

                {property.amenities && property.amenities.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-4 text-lg">Équipements</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                      {property.amenities.map((amenity: string, index: number) => (
                        <div key={index} className="flex items-center space-x-2 p-2 rounded-lg bg-muted/50">
                          {getAmenityIcon(amenity)}
                          <span className="text-sm">{amenity}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Contact Sidebar */}
          <div className="space-y-4">
            <Card className="glass">
              <CardHeader>
                <CardTitle className="gradient-text">Contactez le propriétaire</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                {/* Make Offer Button */}
                {canMakeOffer && (
                  <Dialog open={isOfferDialogOpen} onOpenChange={setIsOfferDialogOpen}>
                    <DialogTrigger asChild>
                      <Button className="w-full gradient-button" size="lg">
                        <Banknote className="mr-2 h-4 w-4" />
                        Faire une offre
                      </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-md">
                      <DialogHeader>
                        <DialogTitle>Faire une offre</DialogTitle>
                      </DialogHeader>
                      <Form {...form}>
                        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                          <FormField
                            control={form.control}
                            name="monthlyRent"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>Montant proposé (TND/mois)</FormLabel>
                                <FormControl>
                                  <Input
                                    placeholder={`Prix affiché: ${property.price} TND`}
                                    {...field}
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name="conditions"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel>Message au propriétaire</FormLabel>
                                <FormControl>
                                  <Textarea
                                    placeholder="Expliquez pourquoi vous êtes intéressé par cette propriété..."
                                    {...field}
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <Button 
                            type="submit" 
                            className="w-full"
                            disabled={createOfferMutation.isPending}
                          >
                            {createOfferMutation.isPending ? "Envoi en cours..." : "Envoyer l'offre"}
                          </Button>
                        </form>
                      </Form>
                    </DialogContent>
                  </Dialog>
                )}

                {/* Contact Buttons */}
                <div className="space-y-2">
                  <Button variant="outline" className="w-full">
                    <Phone className="mr-2 h-4 w-4" />
                    Appeler
                  </Button>
                  <Button variant="outline" className="w-full">
                    <MessageCircle className="mr-2 h-4 w-4" />
                    Message
                  </Button>
                </div>

                {/* Owner Info */}
                <div className="pt-4 border-t">
                  <h4 className="font-medium mb-3">Propriétaire</h4>
                  <div className="flex items-center space-x-3">
                    <div className="w-12 h-12 gradient-button rounded-full flex items-center justify-center text-white font-semibold">
                      {property.ownerId}
                    </div>
                    <div>
                      <p className="font-medium">Propriétaire #{property.ownerId}</p>
                      <p className="text-sm text-muted-foreground">
                        {property.status === "Disponible" ? "Disponible" : "Occupé"}
                      </p>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
}

