import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import Header from "@/components/Header";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Checkbox } from "@/components/ui/checkbox";
import { 
  Search as SearchIcon, 
  MapPin, 
  Filter, 
  Heart, 
  Star, 
  Wifi, 
  Car, 
  GraduationCap,
  Users,
  Home,
  Maximize
} from "lucide-react";

const Search = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [priceRange, setPriceRange] = useState([0, 2000]);
  const [propertyType, setPropertyType] = useState("");
  const [location, setLocation] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [categoryFilter, setCategoryFilter] = useState("");
  const [, navigate] = useLocation();

  // Mock properties data
  const mockProperties = [
    {
      id: 1,
      title: "Studio moderne près INSAT",
      price: 450,
      priceType: "mois",
      location: "Ariana, Raoued",
      distance: "200m de l'INSAT",
      rating: 4.8,
      reviews: 24,
      type: "studio",
      amenities: ["wifi", "furnished", "parking"],
      images: ["/placeholder.svg"],
      isStudentFriendly: true,
      owner: "Ahmed Karim",
      available: true
    },
    {
      id: 2,
      title: "Appartement 2 pièces famille",
      price: 680,
      priceType: "mois",
      location: "Tunis, Bardo",
      distance: "5 min de l'école primaire",
      rating: 4.6,
      reviews: 18,
      type: "apartment",
      amenities: ["wifi", "garden", "security"],
      images: ["/placeholder.svg"],
      isFamilyFriendly: true,
      owner: "Fatma Ben Ali",
      available: true
    },
    {
      id: 3,
      title: "Villa avec jardin sécurisé",
      price: 1200,
      priceType: "mois",
      location: "Sidi Bou Saïd",
      distance: "10 min du centre",
      rating: 4.9,
      reviews: 32,
      type: "villa",
      amenities: ["wifi", "garden", "parking", "security"],
      images: ["/placeholder.svg"],
      isFamilyFriendly: true,
      owner: "Mohamed Trabelsi",
      available: true
    },
    {
      id: 4,
      title: "Studio étudiant meublé",
      price: 380,
      priceType: "mois",
      location: "Tunis, Manouba",
      distance: "300m de l'Université Manouba",
      rating: 4.3,
      reviews: 15,
      type: "studio",
      amenities: ["wifi", "furnished"],
      images: ["/placeholder.svg"],
      isStudentFriendly: true,
      owner: "Leila Mansouri",
      available: false
    }
  ];

  const [filteredProperties, setFilteredProperties] = useState(mockProperties);

  useEffect(() => {
    // Get user location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => setUserLocation(position),
        (error) => console.log("Location access denied")
      );
    }
  }, []);

  const handleLocationSearch = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation(position);
          // Filter properties within 5km radius (mock calculation)
          const nearbyProperties = mockProperties.filter(p => 
            p.location.includes("Tunis") || p.location.includes("Ariana")
          );
          setFilteredProperties(nearbyProperties);
          console.log("📍 Position trouvée:", position.coords.latitude, position.coords.longitude);
        },
        (error) => {
          console.log("Erreur de géolocalisation:", error);
          // Fallback to nearby properties
          const nearbyProperties = mockProperties.filter(p => 
            p.location.includes("Tunis") || p.location.includes("Ariana")
          );
          setFilteredProperties(nearbyProperties);
        }
      );
    }
  };

  const handleSearch = () => {
    let filtered = mockProperties;

    if (searchQuery) {
      filtered = filtered.filter(p => 
        p.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.location.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    if (propertyType && propertyType !== "all") {
      filtered = filtered.filter(p => p.type === propertyType);
    }

    filtered = filtered.filter(p => p.price >= priceRange[0] && p.price <= priceRange[1]);

    setFilteredProperties(filtered);
  };

  useEffect(() => {
    handleSearch();
  }, [searchQuery, propertyType, priceRange]);

  const getAmenityIcon = (amenity: string) => {
    switch (amenity) {
      case "wifi": return <Wifi className="h-4 w-4" />;
      case "parking": return <Car className="h-4 w-4" />;
      case "furnished": return <Home className="h-4 w-4" />;
      case "garden": return <span className="text-green-500">🌿</span>;
      case "security": return <span>🔒</span>;
      default: return <span>✓</span>;
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8">
        {/* Search Header */}
        <div className="glass-card p-6 mb-8">
          <h1 className="text-3xl font-bold gradient-text mb-6">Trouvez votre lieu idéal</h1>

          {/* Search Bar */}
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <div className="relative">
                <SearchIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-muted-foreground" />
                <Input
                  placeholder="Rechercher par ville, quartier, université..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            {/* Category Filters */}
            <div className="flex flex-wrap gap-2">
              <Button 
                variant={categoryFilter === "student" ? "default" : "outline"}
                size="sm"
                onClick={() => setCategoryFilter(categoryFilter === "student" ? "" : "student")}
              >
                Pour étudiants
              </Button>
              <Button 
                variant={categoryFilter === "family" ? "default" : "outline"}
                size="sm"
                onClick={() => setCategoryFilter(categoryFilter === "family" ? "" : "family")}
              >
                Pour familles
              </Button>
            </div>

            <Button 
              variant="outline" 
              onClick={handleLocationSearch}
              className="flex items-center space-x-2"
            >
              <MapPin className="h-4 w-4" />
              <span>📍 Me localiser</span>
            </Button>

            {/* Via Map Link */}
            <Button 
              variant="outline" 
              onClick={() => navigate("/map")}
              className="w-full md:w-auto"
            >
              <MapPin className="h-4 w-4 mr-2" />
              Via Maps
            </Button>

            <Button 
              variant="outline" 
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center space-x-2"
            >
              <Filter className="h-4 w-4" />
              <span>Filtres</span>
            </Button>
          </div>

          {/* Quick Filters */}
          <div className="flex flex-wrap gap-2">
            <Button 
              variant={propertyType === "studio" ? "default" : "outline"} 
              size="sm"
              onClick={() => setPropertyType(propertyType === "studio" ? "" : "studio")}
            >
              🎓 Étudiants
            </Button>
            <Button 
              variant={propertyType === "apartment" ? "default" : "outline"} 
              size="sm"
              onClick={() => setPropertyType(propertyType === "apartment" ? "" : "apartment")}
            >
              👨‍👩‍👧‍👦 Familles
            </Button>
            <Button variant="outline" size="sm">
              🏠 Meublé
            </Button>
            <Button variant="outline" size="sm">
              🚗 Parking
            </Button>
          </div>
        </div>

        {/* Advanced Filters */}
        {showFilters && (
          <Card className="glass-card mb-8">
            <CardContent className="p-6">
              <h3 className="font-semibold mb-4">Filtres avancés</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div>
                  <label className="text-sm font-medium mb-2 block">Type de bien</label>
                  <Select value={propertyType} onValueChange={setPropertyType}>
                    <SelectTrigger>
                      <SelectValue placeholder="Tous types" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">Tous types</SelectItem>
                      <SelectItem value="studio">Studio</SelectItem>
                      <SelectItem value="apartment">Appartement</SelectItem>
                      <SelectItem value="villa">Villa</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <label className="text-sm font-medium mb-2 block">
                    Prix: {priceRange[0]} - {priceRange[1]} TND/mois
                  </label>
                  <Slider
                    value={priceRange}
                    onValueChange={setPriceRange}
                    max={2000}
                    min={0}
                    step={50}
                    className="mt-2"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium mb-2 block">Équipements</label>
                  <div className="space-y-2">
                    <div className="flex items-center space-x-2">
                      <Checkbox id="wifi" />
                      <label htmlFor="wifi" className="text-sm">Wi-Fi inclus</label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Checkbox id="furnished" />
                      <label htmlFor="furnished" className="text-sm">Meublé</label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Checkbox id="parking" />
                      <label htmlFor="parking" className="text-sm">Parking</label>
                    </div>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Results */}
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-semibold">
            {filteredProperties.length} bien(s) trouvé(s)
          </h2>
          <Select defaultValue="price" onValueChange={(value) => {
            let sorted = [...filteredProperties];
            switch(value) {
              case "price":
                sorted.sort((a, b) => a.price - b.price);
                break;
              case "price-desc":
                sorted.sort((a, b) => b.price - a.price);
                break;
              case "rating":
                sorted.sort((a, b) => b.rating - a.rating);
                break;
              case "distance":
                // Mock distance sorting
                sorted.sort((a, b) => parseInt(a.distance) - parseInt(b.distance));
                break;
            }
            setFilteredProperties(sorted);
          }}>
            <SelectTrigger className="w-48">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="price">Prix croissant</SelectItem>
              <SelectItem value="price-desc">Prix décroissant</SelectItem>
              <SelectItem value="rating">Mieux notés</SelectItem>
              <SelectItem value="distance">Plus proches</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Property Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProperties.map((property) => (
            <Card 
              key={property.id} 
              className="glass-card cursor-pointer hover:scale-105 transition-transform"
              onClick={() => navigate(`/property/${property.id}`)}
            >
              <CardContent className="p-0">
                {/* Image */}
                <div className="relative h-48 bg-muted rounded-t-lg overflow-hidden">
                  <div className="absolute inset-0 flex items-center justify-center">
                    <Home className="h-12 w-12 text-muted-foreground" />
                  </div>
                  <Button 
                    variant="ghost" 
                    size="icon" 
                    className="absolute top-2 right-2 bg-white/20 backdrop-blur-sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      // Add to favorites
                      const favorites = JSON.parse(localStorage.getItem("userFavorites") || "[]");
                      const isAlreadyFavorite = favorites.some((fav: any) => fav.id === property.id);

                      if (!isAlreadyFavorite) {
                        const newFavorite = { ...property, addedToFavorites: new Date().toISOString() };
                        favorites.push(newFavorite);
                        localStorage.setItem("userFavorites", JSON.stringify(favorites));
                        console.log("❤️ Ajouté aux favoris:", property.title);
                      }
                    }}
                  >
                    <Heart className="h-4 w-4" />
                  </Button>
                  {!property.available && (
                    <Badge className="absolute bottom-2 left-2" variant="destructive">
                      Non disponible
                    </Badge>
                  )}
                  {property.isStudentFriendly && (
                    <Badge className="absolute top-2 left-2" variant="default">
                      <GraduationCap className="h-3 w-3 mr-1" />
                      Étudiant
                    </Badge>
                  )}
                  {property.isFamilyFriendly && (
                    <Badge className="absolute top-2 left-2" variant="default">
                      <Users className="h-3 w-3 mr-1" />
                      Famille
                    </Badge>
                  )}
                </div>

                {/* Content */}
                <div className="p-4">
                  <h3 className="font-semibold text-lg mb-2">{property.title}</h3>
                  <p className="text-primary font-bold text-xl mb-2">
                    {property.price} TND/{property.priceType}
                  </p>

                  <div className="flex items-center text-sm text-muted-foreground mb-2">
                    <MapPin className="h-3 w-3 mr-1" />
                    <span>{property.location}</span>
                  </div>

                  <div className="flex items-center text-sm text-muted-foreground mb-3">
                    <span className="text-accent">📍 {property.distance}</span>
                  </div>

                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center space-x-1">
                      <Star className="h-4 w-4 fill-warning text-warning" />
                      <span className="text-sm font-medium">{property.rating}</span>
                      <span className="text-sm text-muted-foreground">
                        ({property.reviews} avis)
                      </span>
                    </div>
                  </div>

                  {/* Amenities */}
                  <div className="flex flex-wrap gap-1 mb-3">
                    {property.amenities.slice(0, 3).map((amenity) => (
                      <Badge key={amenity} variant="outline" className="text-xs">
                        {getAmenityIcon(amenity)}
                      </Badge>
                    ))}
                    {property.amenities.length > 3 && (
                      <Badge variant="outline" className="text-xs">
                        +{property.amenities.length - 3}
                      </Badge>
                    )}
                  </div>

                  <div className="text-xs text-muted-foreground">
                    Par {property.owner}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {filteredProperties.length === 0 && (
          <div className="text-center py-12">
            <Home className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-lg font-semibold mb-2">Aucun bien trouvé</h3>
            <p className="text-muted-foreground">
              Essayez de modifier vos critères de recherche
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Search;

client/src/pages/Signup.tsx.content:
import { useState } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { MapPin, GraduationCap, Users, Building, Upload } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const Signup = () => {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    confirmPassword: "",
    firstName: "",
    lastName: "",
    phone: "",
    userType: "",
    cinNumber: "",
    profilePicture: null as File | null,
    acceptTerms: false,
    studentInfo: {
      university: "",
      studentId: ""
    },
    socialAccounts: {
      facebook: "",
      instagram: "",
      linkedin: ""
    }
  });
  const [, navigate] = useLocation();
  const { toast } = useToast();

  const universities = [
    "Université de Tunis El Manar",
    "Université de Sfax", 
    "INSAT",
    "ENSI",
    "IHEC",
    "ESC Tunis",
    "Autre"
  ];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.password !== formData.confirmPassword) {
      toast({
        title: "Erreur",
        description: "Les mots de passe ne correspondent pas.",
        variant: "destructive",
      });
      return;
    }

    if (!formData.acceptTerms) {
      toast({
        title: "Erreur",
        description: "Vous devez accepter les conditions générales d'utilisation.",
        variant: "destructive",
      });
      return;
    }

    // Mock registration
    localStorage.setItem("isAuthenticated", "true");
    localStorage.setItem("userEmail", formData.email);
    localStorage.setItem("userType", formData.userType);
    localStorage.setItem("userProfile", JSON.stringify(formData));

    // Special message for owners
    if (formData.userType === "owner") {
      toast({
        title: "Compte créé - En attente de validation",
        description: "Votre compte propriétaire est en attente de validation par un administrateur. L'activation définitive se fera après paiement.",
      });
    } else {
      toast({
        title: "Inscription réussie!",
        description: "Votre compte a été créé avec succès.",
      });
    }

    navigate("/dashboard");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFormData({ ...formData, profilePicture: file });
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <Card className="w-full max-w-2xl glass-card">
        <CardHeader className="text-center">
          <div className="flex items-center justify-center space-x-2 mb-4">
            <div className="gradient-primary p-2 rounded-xl">
              <MapPin className="h-6 w-6 text-white" />
            </div>
            <h1 className="text-2xl font-bold gradient-text">Ekrili</h1>
          </div>
          <CardTitle className="text-2xl">Créer un compte</CardTitle>
          <CardDescription>
            Rejoignez la communauté Ekrili
          </CardDescription>
        </CardHeader>
        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-6">
            {/* Type d'utilisateur */}
            <div className="space-y-3">
              <Label>Je suis...</Label>
              <RadioGroup
                value={formData.userType}
                onValueChange={(value) => setFormData({ ...formData, userType: value })}
                className="grid grid-cols-3 gap-4"
              >
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="tenant" id="tenant" />
                  <Label htmlFor="tenant" className="flex items-center space-x-2 cursor-pointer">
                    <Users className="h-4 w-4" />
                    <span>Locataire</span>
                  </Label>
                </div>
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="student" id="student" />
                  <Label htmlFor="student" className="flex items-center space-x-2 cursor-pointer">
                    <GraduationCap className="h-4 w-4" />
                    <span>Étudiant</span>
                  </Label>
                </div>
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="owner" id="owner" />
                  <Label htmlFor="owner" className="flex items-center space-x-2 cursor-pointer">
                    <Building className="h-4 w-4" />
                    <span>Propriétaire</span>
                  </Label>
                </div>
              </RadioGroup>
            </div>

            {/* Informations personnelles */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="firstName">Prénom</Label>
                <Input
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="lastName">Nom</Label>
                <Input
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="phone">Téléphone *</Label>
              <Input
                id="phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                placeholder="+216 XX XXX XXX"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="cinNumber">3 derniers chiffres de la CIN/Passeport *</Label>
              <Input
                id="cinNumber"
                value={formData.cinNumber}
                onChange={(e) => setFormData({ ...formData, cinNumber: e.target.value })}
                placeholder="123"
                maxLength={3}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="profilePicture">Photo de profil (facultative)</Label>
              <Input
                id="profilePicture"
                type="file"
                accept="image/*"
                onChange={handleFileUpload}
              />
              {formData.profilePicture && (
                <p className="text-sm text-success">✓ Photo sélectionnée: {formData.profilePicture.name}</p>
              )}
            </div>

            {/* Social Accounts */}
            <div className="space-y-4 p-4 glass-card rounded-lg">
              <h3 className="font-semibold">Comptes sociaux (facultatif)</h3>
              <div className="grid grid-cols-1 gap-2">
                <Input
                  placeholder="Profil Facebook"
                  value={formData.socialAccounts.facebook}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, facebook: e.target.value }
                  })}
                />
                <Input
                  placeholder="Profil Instagram"
                  value={formData.socialAccounts.instagram}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, instagram: e.target.value }
                  })}
                />
                <Input
                  placeholder="Profil LinkedIn"
                  value={formData.socialAccounts.linkedin}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, linkedin: e.target.value }
                  })}
                />
              </div>
            </div>

            {/* Informations étudiant */}
            {formData.userType === "student" && (
              <div className="space-y-4 p-4 glass-card rounded-lg">
                <h3 className="font-semibold flex items-center space-x-2">
                  <GraduationCap className="h-4 w-4" />
                  <span>Informations étudiant</span>
                </h3>
                <div className="space-y-2">
                  <Label>Université</Label>
                  <Select
                    value={formData.studentInfo.university}
                    onValueChange={(value) => 
                      setFormData({ 
                        ...formData, 
                        studentInfo: { ...formData.studentInfo, university: value }
                      })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionnez votre université" />
                    </SelectTrigger>
                    <SelectContent>
                      {universities.map((uni) => (
                        <SelectItem key={uni} value={uni}>{uni}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="studentId">Numéro étudiant</Label>
                  <Input
                    id="studentId"
                    value={formData.studentInfo.studentId}
                    onChange={(e) => 
                      setFormData({ 
                        ...formData, 
                        studentInfo: { ...formData.studentInfo, studentId: e.target.value }
                      })
                    }
                  />
                </div>
              </div>
            )}

            {/* Mots de passe */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="password">Mot de passe</Label>
                <Input
                  id="password"
                  type="password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="confirmPassword">Confirmer le mot de passe</Label>
                <Input
                  id="confirmPassword"
                  type="password"
                  value={formData.confirmPassword}
                  onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                  required
                />
              </div>
            </div>
            {/* Terms and Conditions */}
            <div className="flex items-center space-x-2">
              <Checkbox
                id="acceptTerms"
                checked={formData.acceptTerms}
                onCheckedChange={(checked) => setFormData({ ...formData, acceptTerms: checked as boolean })}
              />
              <Label htmlFor="acceptTerms" className="text-sm cursor-pointer">
                J'accepte les{" "}
                <a href="/terms" className="text-primary hover:underline">conditions générales d'utilisation</a>
                {" "}et la{" "}
                <a href="/privacy" className="text-primary hover:underline">politique de confidentialité</a>
              </Label>
            </div>
          </CardContent>
          <CardFooter className="flex flex-col space-y-4">
            <Button 
              type="submit" 
              className="w-full" 
              disabled={!formData.userType || !formData.acceptTerms}
            >
              Créer mon compte
            </Button>
            <p className="text-sm text-muted-foreground text-center">
              Déjà un compte?{" "}
              <Link to="/login" className="text-primary hover:underline">
                Se connecter
              </Link>
            </p>
          </CardFooter>
        </form>
      </Card>
    </div>
  );
};

export default Signup;

client/src/pages/UserProfile.tsx.content:
import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import Header from "@/components/Header";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { 
  User, 
  Mail, 
  Phone, 
  MapPin, 
  Edit,
  ArrowLeft,
  Star,
  CheckCircle,
  Upload,
  Shield
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const UserProfile = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [editData, setEditData] = useState<any>({});
  const [, navigate] = useLocation();
  const { toast } = useToast();

  useEffect(() => {
    const isAuth = localStorage.getItem("isAuthenticated");
    if (!isAuth) {
      navigate("/login");
      return;
    }

    const profile = JSON.parse(localStorage.getItem("userProfile") || "{}");
    setUserProfile(profile);
    setEditData(profile);
  }, [navigate]);

  const getUserBadges = () => {
    const badges = [];
    if (userProfile?.email && userProfile?.phone && userProfile?.cinNumber) {
      badges.push({ label: "Compte vérifié", icon: "✅", color: "success" });
    }
    if (userProfile?.userType === "owner") {
      badges.push({ label: "Propriétaire actif", icon: "📷", color: "default" });
    }
    badges.push({ label: "Membre", icon: "🎖", color: "secondary" });
    return badges;
  };

  const handleSave = () => {
    localStorage.setItem("userProfile", JSON.stringify(editData));
    setUserProfile(editData);
    setIsEditing(false);

    toast({
      title: "Profil mis à jour",
      description: "Vos informations ont été sauvegardées",
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setEditData({ ...editData, profilePicture: file });
      toast({
        title: "Photo mise à jour",
        description: "Votre nouvelle photo de profil a été sélectionnée",
      });
    }
  };

  if (!userProfile) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8">
          <p>Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex items-center mb-8">
          <Button 
            variant="ghost" 
            onClick={() => navigate("/dashboard")}
            className="mr-4"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Retour
          </Button>
          <div className="flex-1">
            <h1 className="text-3xl font-bold gradient-text flex items-center space-x-3">
              <User className="h-8 w-8 text-primary" />
              <span>Mon Profil</span>
            </h1>
          </div>
          <Button 
            onClick={() => isEditing ? handleSave() : setIsEditing(true)}
            variant={isEditing ? "default" : "outline"}
          >
            <Edit className="h-4 w-4 mr-2" />
            {isEditing ? "Sauvegarder" : "Modifier"}
          </Button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Profile Info */}
          <div className="lg:col-span-2 space-y-6">
            <Card className="glass-card">
              <CardHeader>
                <CardTitle>Informations personnelles</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label>Prénom</Label>
                    {isEditing ? (
                      <Input
                        value={editData.firstName || ""}
                        onChange={(e) => setEditData({ ...editData, firstName: e.target.value })}
                      />
                    ) : (
                      <p className="p-2 bg-muted rounded">{userProfile.firstName}</p>
                    )}
                  </div>
                  <div>
                    <Label>Nom</Label>
                    {isEditing ? (
                      <Input
                        value={editData.lastName || ""}
                        onChange={(e) => setEditData({ ...editData, lastName: e.target.value })}
                      />
                    ) : (
                      <p className="p-2 bg-muted rounded">{userProfile.lastName}</p>
                    )}
                  </div>
                </div>

                <div>
                  <Label>Email</Label>
                  {isEditing ? (
                    <Input
                      value={editData.email || ""}
                      onChange={(e) => setEditData({ ...editData, email: e.target.value })}
                      type="email"
                    />
                  ) : (
                    <p className="p-2 bg-muted rounded flex items-center space-x-2">
                      <Mail className="h-4 w-4" />
                      <span>{userProfile.email}</span>
                    </p>
                  )}
                </div>

                <div>
                  <Label>Téléphone</Label>
                  {isEditing ? (
                    <Input
                      value={editData.phone || ""}
                      onChange={(e) => setEditData({ ...editData, phone: e.target.value })}
                    />
                  ) : (
                    <p className="p-2 bg-muted rounded flex items-center space-x-2">
                      <Phone className="h-4 w-4" />
                      <span>{userProfile.phone}</span>
                    </p>
                  )}
                </div>

                {userProfile.userType === "student" && userProfile.studentInfo && (
                  <div className="space-y-2">
                    <Label>Informations étudiant</Label>
                    <div className="p-3 glass-card rounded-lg space-y-2">
                      <p><strong>Université:</strong> {userProfile.studentInfo.university}</p>
                      <p><strong>Numéro étudiant:</strong> {userProfile.studentInfo.studentId}</p>
                    </div>
                  </div>
                )}

                {isEditing && (
                  <div>
                    <Label>Photo de profil</Label>
                    <Input
                      type="file"
                      accept="image/*"
                      onChange={handleFileUpload}
                    />
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Verification */}
            <Card className="glass-card">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <Shield className="h-5 w-5" />
                  <span>Vérification d'identité</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="text-center">
                    <div className={`p-4 rounded-lg ${userProfile.email ? 'bg-success/10' : 'bg-muted'}`}>
                      <Mail className={`h-6 w-6 mx-auto mb-2 ${userProfile.email ? 'text-success' : 'text-muted-foreground'}`} />
                      <p className="text-sm">Email</p>
                      {userProfile.email ? (
                        <CheckCircle className="h-4 w-4 text-success mx-auto mt-1" />
                      ) : (
                        <Button size="sm" variant="outline" className="mt-1">Vérifier</Button>
                      )}
                    </div>
                  </div>

                  <div className="text-center">
                    <div className={`p-4 rounded-lg ${userProfile.phone ? 'bg-success/10' : 'bg-muted'}`}>
                      <Phone className={`h-6 w-6 mx-auto mb-2 ${userProfile.phone ? 'text-success' : 'text-muted-foreground'}`} />
                      <p className="text-sm">Téléphone</p>
                      {userProfile.phone ? (
                        <CheckCircle className="h-4 w-4 text-success mx-auto mt-1" />
                      ) : (
                        <Button size="sm" variant="outline" className="mt-1">Vérifier</Button>
                      )}
                    </div>
                  </div>

                  <div className="text-center">
                    <div className={`p-4 rounded-lg ${userProfile.cinNumber ? 'bg-success/10' : 'bg-muted'}`}>
                      <User className={`h-6 w-6 mx-auto mb-2 ${userProfile.cinNumber ? 'text-success' : 'text-muted-foreground'}`} />
                      <p className="text-sm">CIN/Passeport</p>
                      {userProfile.cinNumber ? (
                        <CheckCircle className="h-4 w-4 text-success mx-auto mt-1" />
                      ) : (
                        <Button size="sm" variant="outline" className="mt-1">Vérifier</Button>
                      )}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Profile Picture */}
            <Card className="glass-card">
              <CardContent className="p-6 text-center">
                <div className="w-24 h-24 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
                  <User className="h-12 w-12 text-primary" />
                </div>
                <h3 className="font-semibold">{userProfile.firstName} {userProfile.lastName}</h3>
                <p className="text-muted-foreground capitalize">{userProfile.userType}</p>
                <Badge variant="outline" className="mt-2">
                  Membre depuis {new Date().getFullYear()}
                </Badge>
              </CardContent>
            </Card>

            {/* Badges */}
            <Card className="glass-card">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <Star className="h-5 w-5" />
                  <span>Badges</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {getUserBadges().map((badge, index) => (
                  <div key={index} className="flex items-center space-x-2 p-2 glass-card rounded">
                    <span>{badge.icon}</span>
                    <span className="text-sm">{badge.label}</span>
                  </div>
                ))}
              </CardContent>
            </Card>

            {/* Stats */}
            {userProfile.userType === "owner" && (
              <Card className="glass-card">
                <CardHeader>
                  <CardTitle>Statistiques</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="text-center">
                    <p className="text-2xl font-bold">0</p>
                    <p className="text-sm text-muted-foreground">Biens publiés</p>
                  </div>
                  <div className="text-center">
                    <p className="text-2xl font-bold">0</p>
                    <p className="text-sm text-muted-foreground">Contrats signés</p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserProfile;

