import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import SignatureCanvas from "react-signature-canvas";
import { FileText, Download, PenTool, X } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";

interface ContractGeneratorProps {
  contract: any;
  onSign: (signatureData: any) => void;
  isLoading?: boolean;
  currentUserId?: number;
}

export default function ContractGenerator({ contract, onSign, isLoading = false, currentUserId = 1 }: ContractGeneratorProps) {
  const [signatureCanvas, setSignatureCanvas] = useState<SignatureCanvas | null>(null);
  const [showSignatureCanvas, setShowSignatureCanvas] = useState(false);
  const { toast } = useToast();

  // Determine user role based on contract data
  const userRole: 'owner' | 'tenant' = currentUserId === contract.ownerId ? 'owner' : 'tenant';

  const canSign = () => {
    if (userRole === 'owner' && !contract.ownerSignature) return true;
    if (userRole === 'tenant' && contract.ownerSignature && !contract.tenantSignature) return true;
    return false;
  };

  const handleSign = () => {
    if (!signatureCanvas || signatureCanvas.isEmpty()) {
      toast({
        title: "Signature requise",
        description: "Veuillez signer avant de valider",
        variant: "destructive",
      });
      return;
    }

    const signatureData = signatureCanvas.toDataURL();
    onSign({
      signatureType: userRole,
      signatureData: signatureData
    });
    setShowSignatureCanvas(false);

    toast({
      title: "Signature enregistrée",
      description: "Votre signature a été ajoutée au contrat",
    });
  };

  const clearSignature = () => {
    if (signatureCanvas) {
      signatureCanvas.clear();
    }
  };

  const generatePDF = async () => {
    const contractElement = document.getElementById('contract-content');
    if (!contractElement) return;

    try {
      const canvas = await html2canvas(contractElement);
      const imgData = canvas.toDataURL('image/png');

      const pdf = new jsPDF();
      const imgWidth = 210;
      const pageHeight = 295;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;

      let position = 0;

      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft >= 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      pdf.save(`contrat-${contract.id}.pdf`);

      toast({
        title: "PDF généré",
        description: "Le contrat a été téléchargé avec succès",
      });
    } catch (error) {
      toast({
        title: "Erreur",
        description: "Impossible de générer le PDF",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="space-y-6">
      {/* Contract Display */}
      <Card className="glass-card">
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <FileText className="h-5 w-5" />
            <span>Contrat de Location #{contract.id}</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div id="contract-content" className="space-y-4 text-sm max-w-4xl mx-auto p-6 bg-white text-black">
            <div className="text-center font-bold text-xl mb-8">
              CONTRAT DE LOCATION
            </div>

            <div className="text-center mb-6">
              <p>Pour</p>
              <p className="font-semibold">un appartement meublé/non meublé</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">ENTRE LES SOUSSIGNÉS :</p>
              <div className="ml-4 space-y-2">
                <p><strong>Le BAILLEUR:</strong> M. {contract.contractData?.landlordName || "Propriétaire"}</p>
                {contract.contractData?.landlordCin && (
                  <p className="ml-4">CIN: {contract.contractData.landlordCin}</p>
                )}
                <p><strong>Le PRENEUR:</strong> M. {contract.contractData?.tenantName || "Locataire"}</p>
                {contract.contractData?.tenantCin && (
                  <p className="ml-4">CIN: {contract.contractData.tenantCin}</p>
                )}
              </div>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">IL A ÉTÉ CONVENU CE QUI SUIT :</p>
              <div className="ml-4 space-y-2">
                <p>Le bailleur loue à M. {contract.contractData?.tenantName || "Locataire"}</p>
                <p><strong>Propriété:</strong> {contract.contractData?.propertyTitle || "Propriété"}</p>
                <p><strong>Adresse:</strong> {contract.contractData?.propertyAddress || "Adresse non spécifiée"}</p>
              </div>
            </div>

            <div className="mb-6">
              <p>Il appartient aux deux parties de constater et d'établir, par acte séparé dressé contradictoirement, l'état des lieux et la connaissance du mobilier si les locaux sont loués meublés.</p>
            </div>

            <div className="mb-6">
              <p><strong>DURÉE DU BAIL:</strong></p>
              <p className="ml-4">
                Le bail est fait pour une durée déterminée du{" "}
                {contract.contractData?.startDate ? new Date(contract.contractData.startDate).toLocaleDateString('fr-FR') : "__/__/__"}{" "}
                au{" "}
                {contract.contractData?.endDate ? new Date(contract.contractData.endDate).toLocaleDateString('fr-FR') : "__/__/__"}
              </p>
            </div>

            <div className="mb-6">
              <p>Le preneur pourra le dénoncer avec un préavis de trois mois entiers par lettre recommandée avec accusé de réception pendant le contrat.</p>
              <p>Le bailleur pourra le dénoncer avec un préavis d'un mois entier par lettre recommandée avec accusé de réception pendant le contrat pour un motif sérieux et légitime et conformément aux dispositions prévues par la loi.</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">OBLIGATIONS DU PRENEUR:</p>
              <p>Le présent contrat est fait aux conditions ordinaires et de droit en pareille matière à savoir la loi du 01/09/1948 ou les règles générales établies par le Code Civil. Le preneur et le bailleur s'engagent à respecter leurs obligations réciproques et notamment le preneur en vertu des obligations suivantes concernant le bon ordre et la tenue de l'immeuble et surtout l'entretien constant des locaux loués. Il devra payer le loyer au premier du mois.</p>
              <p><strong>Ce loyer s'élève actuellement à {contract.contractData?.monthlyRent || "___"} TND</strong></p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">CAUTION:</p>
              <p>Le montant de la caution s'élève à {contract.contractData?.deposit || "___"} TND</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">CLAUSES SPÉCIALES:</p>
              <p>À défaut de paiement à son échéance d'un seul terme de loyer, comme en cas d'inexécution d'une des obligations mises à la charge du preneur tant par la présente convention que par la loi et deux mois après un commandement de payer ou sommation, déférée par le bailleur, demeure sans effet, la présente location sera résiliée de plein droit sans qu'il y ait à remplir aucune formalité judiciaire.</p>
              <p>Le preneur ne peut en aucun cas procéder à une sous-location ou échange de bail de son logement.</p>
            </div>

            {contract.contractData?.conditions && (
              <div className="mb-6">
                <p className="font-semibold mb-2">CONDITIONS PARTICULIÈRES:</p>
                <p className="ml-4">{contract.contractData.conditions}</p>
              </div>
            )}

            <div className="mb-6">
              <p className="font-semibold">ANNEXE AU PRÉSENT CONTRAT:</p>
              <ul className="ml-4 list-disc">
                <li>Un état des lieux d'entrée plus inventaire (quand meublé)</li>
                <li>Un contrat de garantie</li>
              </ul>
            </div>

            <div className="mb-8">
              <p>Fait en trois exemplaires</p>
              <p>Le {new Date().toLocaleDateString('fr-FR')}</p>
            </div>

            {/* Signatures Section */}
            <div className="mt-12 border-t pt-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="text-center">
                  <p className="font-semibold mb-4">LE BAILLEUR</p>
                  <p className="text-xs mb-2">(ajouter la mention lu et approuvé)</p>
                  {contract.ownerSignature ? (
                    <div className="border rounded p-4 bg-white min-h-[100px] flex flex-col items-center justify-center">
                      <img src={contract.ownerSignature} alt="Signature propriétaire" className="max-h-16 max-w-full" />
                      <p className="text-xs text-muted-foreground mt-2">
                        Signé le {contract.ownerSignedAt ? new Date(contract.ownerSignedAt).toLocaleDateString('fr-FR') : ''}
                      </p>
                    </div>
                  ) : (
                    <div className="border-2 border-dashed border-muted-foreground/30 rounded p-4 text-center text-muted-foreground min-h-[100px] flex items-center justify-center">
                      En attente de signature
                    </div>
                  )}
                </div>

                <div className="text-center">
                  <p className="font-semibold mb-4">LE PRENEUR</p>
                  <p className="text-xs mb-2">(ajouter la mention lu et approuvé)</p>
                  {contract.tenantSignature ? (
                    <div className="border rounded p-4 bg-white min-h-[100px] flex flex-col items-center justify-center">
                      <img src={contract.tenantSignature} alt="Signature locataire" className="max-h-16 max-w-full" />
                      <p className="text-xs text-muted-foreground mt-2">
                        Signé le {contract.tenantSignedAt ? new Date(contract.tenantSignedAt).toLocaleDateString('fr-FR') : ''}
                      </p>
                    </div>
                  ) : (
                    <div className="border-2 border-dashed border-muted-foreground/30 rounded p-4 text-center text-muted-foreground min-h-[100px] flex items-center justify-center">
                      En attente de signature
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <div className="flex justify-between items-center">
        <Button variant="outline" onClick={generatePDF}>
          <Download className="h-4 w-4 mr-2" />
          Télécharger PDF
        </Button>

        {canSign() && (
          <Button onClick={() => setShowSignatureCanvas(true)} disabled={isLoading}>
            <PenTool className="h-4 w-4 mr-2" />
            Signer le contrat
          </Button>
        )}
      </div>

      {/* Signature Modal */}
      {showSignatureCanvas && (
        <Card className="glass-card">
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span>Signature électronique</span>
              <Button variant="ghost" size="sm" onClick={() => setShowSignatureCanvas(false)}>
                <X className="h-4 w-4" />
              </Button>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Signez dans l'espace ci-dessous avec votre souris ou votre doigt
              </p>

              <div className="border-2 border-dashed border-primary/20 rounded-lg">
                <SignatureCanvas
                  ref={(ref) => setSignatureCanvas(ref)}
                  canvasProps={{
                    width: 500,
                    height: 200,
                    className: 'signature-canvas w-full'
                  }}
                />
              </div>

              <div className="flex justify-between">
                <Button variant="outline" onClick={clearSignature}>
                  Effacer
                </Button>
                <Button onClick={handleSign} disabled={isLoading}>
                  {isLoading ? "Signature en cours..." : "Valider la signature"}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/components/ContractStatusBadg.content:
import { Badge } from "@/components/ui/badge";
import { Clock, CheckCircle, FileText, XCircle, AlertTriangle } from "lucide-react";

interface ContractStatusBadgeProps {
  status: string;
  tenantSignDeadline?: string | null;
}

export function ContractStatusBadge({ status, tenantSignDeadline }: ContractStatusBadgeProps) {
  const getStatusInfo = () => {
    switch (status) {
      case 'draft':
        return {
          label: 'Brouillon',
          variant: 'secondary' as const,
          icon: <FileText className="h-3 w-3" />
        };
      case 'owner_signed':
        const isExpired = tenantSignDeadline && new Date() > new Date(tenantSignDeadline);
        return {
          label: isExpired ? 'Expiré' : 'En attente locataire',
          variant: isExpired ? 'destructive' as const : 'default' as const,
          icon: isExpired ? <XCircle className="h-3 w-3" /> : <Clock className="h-3 w-3" />
        };
      case 'fully_signed':
        return {
          label: 'Signé complet',
          variant: 'default' as const,
          icon: <CheckCircle className="h-3 w-3" />
        };
      case 'active':
        return {
          label: 'Actif',
          variant: 'default' as const,
          icon: <CheckCircle className="h-3 w-3" />
        };
      case 'expired':
        return {
          label: 'Expiré',
          variant: 'destructive' as const,
          icon: <XCircle className="h-3 w-3" />
        };
      case 'cancelled':
        return {
          label: 'Annulé',
          variant: 'destructive' as const,
          icon: <XCircle className="h-3 w-3" />
        };
      default:
        return {
          label: status,
          variant: 'secondary' as const,
          icon: <AlertTriangle className="h-3 w-3" />
        };
    }
  };

  const { label, variant, icon } = getStatusInfo();

  return (
    <Badge variant={variant} className="flex items-center gap-1">
      {icon}
      {label}
    </Badge>
  );
}

client/src/components/NotificationCenter.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Bell, X, CheckCircle, Clock, AlertTriangle, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { useLocation } from "wouter";
import { format } from "date-fns";
import { fr } from "date-fns/locale";

interface Notification {
  id: number;
  userId: number;
  title: string;
  message: string;
  type: string;
  relatedId?: number;
  read: boolean;
  createdAt: string;
}

interface NotificationCenterProps {
  userId: number;
}

export function NotificationCenter({ userId }: NotificationCenterProps) {
  const [, navigate] = useLocation();

  // Fetch notifications with polling for real-time updates
  const { data: notifications = [], refetch } = useQuery({
    queryKey: ['/api/notifications', userId],
    queryFn: async () => {
      const response = await fetch(`/api/notifications?userId=${userId}`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to fetch notifications');
      return response.json() as Notification[];
    },
    refetchInterval: 5000, // Poll every 5 seconds for real-time updates
    staleTime: 0,
    gcTime: 0,
  });

  const markReadMutation = useMutation({
    mutationFn: async (notificationId: number) => {
      return apiRequest(`/api/notifications/${notificationId}/read`, {
        method: 'PUT'
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/notifications', userId] });
    }
  });

  const unreadCount = notifications.filter(n => !n.read).length;

  const getNotificationIcon = (type: string) => {
    switch (type) {
      case 'contract_signature_required':
      case 'signature':
        return <FileText className="h-4 w-4 text-blue-500" />;
      case 'contract_active':
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'contract_expired':
        return <Clock className="h-4 w-4 text-red-500" />;
      case 'contract_modified':
        return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      default:
        return <Bell className="h-4 w-4 text-gray-500" />;
    }
  };

  const handleNotificationClick = (notification: Notification) => {
    // Mark as read
    if (!notification.read) {
      markReadMutation.mutate(notification.id);
    }

    // Navigate to related content
    if (notification.type.includes('contract') && notification.relatedId) {
      navigate(`/contract/${notification.relatedId}`);
    }
  };

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="sm" className="relative">
          <Bell className="h-5 w-5" />
          {unreadCount > 0 && (
            <Badge 
              variant="destructive" 
              className="absolute -top-2 -right-2 h-5 w-5 rounded-full p-0 flex items-center justify-center text-xs"
            >
              {unreadCount > 99 ? '99+' : unreadCount}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80 p-0" align="end">
        <Card className="border-0 shadow-none">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm flex items-center justify-between">
              Notifications
              {unreadCount > 0 && (
                <Badge variant="secondary" className="text-xs">
                  {unreadCount} non lues
                </Badge>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <ScrollArea className="h-64">
              {notifications.length === 0 ? (
                <div className="p-4 text-center text-sm text-muted-foreground">
                  Aucune notification
                </div>
              ) : (
                <div className="space-y-1">
                  {notifications.map((notification) => (
                    <div
                      key={notification.id}
                      className={`p-3 border-b cursor-pointer hover:bg-muted/50 transition-colors ${
                        !notification.read ? 'bg-blue-50/50 border-l-4 border-l-blue-500' : ''
                      }`}
                      onClick={() => handleNotificationClick(notification)}
                    >
                      <div className="flex items-start gap-2">
                        {getNotificationIcon(notification.type)}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <p className={`text-sm font-medium truncate ${
                              !notification.read ? 'text-foreground' : 'text-muted-foreground'
                            }`}>
                              {notification.title}
                            </p>
                            {!notification.read && (
                              <div className="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0" />
                            )}
                          </div>
                          <p className="text-xs text-muted-foreground line-clamp-2">
                            {notification.message}
                          </p>
                          <p className="text-xs text-muted-foreground mt-1">
                            {format(new Date(notification.createdAt), 'dd MMM yyyy HH:mm', { locale: fr })}
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </ScrollArea>
          </CardContent>
        </Card>
      </PopoverContent>
    </Popover>
  );
}

client/src/components/OfferModal.tsx.content:
import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon, HandHeart } from "lucide-react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";

interface Property {
  id: number;
  title: string;
  price: string;
  ownerId: number;
}

interface OfferModalProps {
  property: Property;
  isOpen: boolean;
  onClose: () => void;
}

export default function OfferModal({ property, isOpen, onClose }: OfferModalProps) {
  const [startDate, setStartDate] = useState<Date>();
  const [endDate, setEndDate] = useState<Date>();
  const [monthlyRent, setMonthlyRent] = useState(property.price);
  const [deposit, setDeposit] = useState(property.price);
  const [conditions, setConditions] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const offerMutation = useMutation({
    mutationFn: async (offerData: any) => {
      return await apiRequest("/api/offers", {
        method: "POST",
        body: JSON.stringify(offerData),
      });
    },
    onSuccess: () => {
      toast({
        title: "Offre envoyée",
        description: "Votre offre a été transmise au propriétaire",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/offers"] });
      onClose();
      resetForm();
    },
    onError: () => {
      toast({
        title: "Erreur",
        description: "Impossible d'envoyer l'offre",
        variant: "destructive",
      });
    }
  });

  const resetForm = () => {
    setStartDate(undefined);
    setEndDate(undefined);
    setMonthlyRent(property.price);
    setDeposit(property.price);
    setConditions("");
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!startDate || !endDate) {
      toast({
        title: "Dates requises",
        description: "Veuillez sélectionner les dates de début et fin",
        variant: "destructive",
      });
      return;
    }

    // Mock current user - replace with real auth
    const currentUser = JSON.parse(localStorage.getItem("currentUser") || '{"id": 1}');

    const offerData = {
      propertyId: property.id,
      tenantId: currentUser.id,
      ownerId: property.ownerId,
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString(),
      monthlyRent: parseFloat(monthlyRent),
      deposit: parseFloat(deposit),
      conditions: conditions || undefined,
    };

    offerMutation.mutate(offerData);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center space-x-2">
            <HandHeart className="h-5 w-5 text-primary" />
            <span>Faire une offre</span>
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label>Propriété</Label>
            <p className="text-sm text-muted-foreground">{property.title}</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="start-date">Date de début</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className="w-full justify-start text-left font-normal"
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {startDate ? format(startDate, "PPP", { locale: fr }) : "Sélectionner"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={startDate}
                    onSelect={setStartDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div>
              <Label htmlFor="end-date">Date de fin</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className="w-full justify-start text-left font-normal"
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {endDate ? format(endDate, "PPP", { locale: fr }) : "Sélectionner"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={endDate}
                    onSelect={setEndDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="monthly-rent">Loyer mensuel (€)</Label>
              <Input
                id="monthly-rent"
                type="number"
                value={monthlyRent}
                onChange={(e) => setMonthlyRent(e.target.value)}
                min="0"
                step="10"
                required
              />
            </div>

            <div>
              <Label htmlFor="deposit">Dépôt de garantie (€)</Label>
              <Input
                id="deposit"
                type="number"
                value={deposit}
                onChange={(e) => setDeposit(e.target.value)}
                min="0"
                step="10"
                required
              />
            </div>
          </div>

          <div>
            <Label htmlFor="conditions">Conditions particulières (optionnel)</Label>
            <Textarea
              id="conditions"
              placeholder="Précisez vos conditions ou demandes particulières..."
              value={conditions}
              onChange={(e) => setConditions(e.target.value)}
              rows={3}
            />
          </div>

          <div className="flex justify-end space-x-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Annuler
            </Button>
            <Button type="submit" disabled={offerMutation.isPending}>
              {offerMutation.isPending ? "Envoi..." : "Envoyer l'offre"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

client/src/pages/ContractsDashboard.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useLocation } from "wouter";
import { ContractStatusBadge } from "@/components/ContractStatusBadge";
import { NotificationCenter } from "@/components/NotificationCenter";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { FileText, Plus, Eye, Edit } from "lucide-react";

interface Contract {
  id: number;
  status: string;
  contractData: any;
  tenantSignDeadline?: string | null;
  createdAt: string;
  ownerId: number;
  tenantId: number;
  ownerSignature?: string | null;
  tenantSignature?: string | null;
  ownerSignedAt?: string | null;
  tenantSignedAt?: string | null;
}

export default function ContractsDashboard() {
  const [, navigate] = useLocation();
  const currentUserId = 1; // Should come from auth context

  // Fetch user's contracts
  const { data: contracts = [], isLoading } = useQuery({
    queryKey: ['/api/contracts', currentUserId],
    queryFn: async () => {
      const response = await fetch(`/api/contracts?userId=${currentUserId}&ownerOnly=true`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to fetch contracts');
      return response.json();
    },
    refetchInterval: 10000, // Refetch every 10 seconds
  });

  const getContractTitle = (contract: Contract) => {
    return contract.contractData?.propertyTitle || `Contrat #${contract.id}`;
  };

  const getContractRole = (contract: Contract) => {
    return contract.ownerId === currentUserId ? 'Propriétaire' : 'Locataire';
  };

  const canModifyContract = (contract: Contract) => {
    // Owner can modify if:
    // 1. They are the owner
    // 2. Tenant hasn't signed yet
    // 3. Contract is not expired or cancelled
    return contract.ownerId === currentUserId && 
           !contract.tenantSignature && 
           !['expired', 'cancelled'].includes(contract.status);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'text-green-600';
      case 'owner_signed': return 'text-yellow-600';
      case 'fully_signed': return 'text-blue-600';
      case 'expired': return 'text-red-600';
      case 'cancelled': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-muted rounded w-1/3"></div>
          <div className="grid gap-4">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="h-32 bg-muted rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold mb-2">Mes Contrats</h1>
          <p className="text-muted-foreground">
            Gérez vos contrats de location et suivez leur statut
          </p>
        </div>
        <div className="flex items-center gap-4">
          <Button variant="outline" onClick={() => navigate("/notifications")}>
            Notifications
          </Button>
          <Button onClick={() => navigate("/create-contract")}>
            <Plus className="h-4 w-4 mr-2" />
            Nouveau Contrat
          </Button>
        </div>
      </div>

      {contracts.length === 0 ? (
        <Card className="text-center py-12">
          <CardContent>
            <FileText className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">Aucun contrat trouvé</h3>
            <p className="text-muted-foreground mb-6">
              Vous n'avez pas encore de contrats. Créez votre premier contrat pour commencer.
            </p>
            <Button onClick={() => navigate("/create-contract")}>
              <Plus className="h-4 w-4 mr-2" />
              Créer un contrat
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4">
          {contracts.map((contract) => (
            <Card key={contract.id} className="hover:shadow-md transition-shadow">
              <CardHeader>
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <CardTitle className="text-lg">
                        {getContractTitle(contract)}
                      </CardTitle>
                      <ContractStatusBadge 
                        status={contract.status} 
                        tenantSignDeadline={contract.tenantSignDeadline}
                      />
                      <Badge variant="outline" className="text-xs">
                        {getContractRole(contract)}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-4 text-sm text-muted-foreground">
                      <span>Contrat #{contract.id}</span>
                      <span>Créé le {format(new Date(contract.createdAt), 'dd MMM yyyy', { locale: fr })}</span>
                      {contract.tenantSignDeadline && contract.status === 'owner_signed' && (
                        <span className="text-yellow-600 font-medium">
                          Échéance: {format(new Date(contract.tenantSignDeadline), 'dd MMM yyyy HH:mm', { locale: fr })}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => navigate(`/contract/${contract.id}`)}
                    >
                      <Eye className="h-4 w-4 mr-2" />
                      Voir
                    </Button>
                    {canModifyContract(contract) && (
                      <Button 
                        variant="outline" 
                        size="sm"
                        onClick={() => navigate(`/create-contract?edit=${contract.id}`)}
                      >
                        <Edit className="h-4 w-4 mr-2" />
                        Modifier
                      </Button>
                    )}
                  </div>
                </div>
              </CardHeader>
              {contract.contractData?.propertyAddress && (
                <CardContent className="pt-0">
                  <p className="text-sm text-muted-foreground">
                    📍 {contract.contractData.propertyAddress}
                  </p>
                  {contract.contractData?.monthlyRent && (
                    <p className="text-sm font-medium mt-1">
                      💰 {contract.contractData.monthlyRent}€/mois
                    </p>
                  )}
                </CardContent>
              )}
            </Card>
          ))}
        </div>
      )}

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mt-8">
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-green-600">
              {contracts.filter(c => c.status === 'active').length}
            </div>
            <div className="text-sm text-muted-foreground">Actifs</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-yellow-600">
              {contracts.filter(c => c.status === 'owner_signed').length}
            </div>
            <div className="text-sm text-muted-foreground">En attente</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-blue-600">
              {contracts.filter(c => c.status === 'fully_signed').length}
            </div>
            <div className="text-sm text-muted-foreground">Signés</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-2xl font-bold text-red-600">
              {contracts.filter(c => c.status === 'expired').length}
            </div>
            <div className="text-sm text-muted-foreground">Expirés</div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

